message.content:
[
  {
    "sys_consequence_reasoning": "Five lives against one is the trade-off that decides it for me",
    "ce_mental_state_attribution": "nobody wants to be the person who tells someone else to stay behind",
    "ce_contextual_explanation": "so I'd take that off their shoulders fast",
    "ce_supportive_use": "take that off their shoulders fast",
    "ae_welfare_concern": "Better that I make the call cleanly than leave five people frozen"
  },
  {
    "sys_consistent_procedure": "push for drawing lots right away",
    "ce_mental_state_attribution": "everyone wants a fair shot and would hate a shouting match",
    "sys_fairness_reciprocity": "a quick random draw gives each person the same chance",
    "sys_consequence_reasoning": "fairness against speed, and lots give us both"
  },
  {
    "ce_mental_state_attribution": "assume they might feel pressured",
    "ce_supportive_use": "check that they truly mean it before we let them stay",
    "sys_rule_justification": "Nobody should be guilted into this",
    "sys_consequence_reasoning": "willing sacrifice against a coerced one"
  },
  {
    "sys_consequence_reasoning": "One loss beats possibly more if we argue",
    "ce_mental_state_attribution": "expect the five leaving to feel guilty later",
    "ce_supportive_use": "tell each one plainly that this was my choice",
    "pda_other_regret_expectation": "expect the five leaving to feel guilty later"
  },
  {
    "sys_fairness_reciprocity": "My life counts as much as anyone's there",
    "ce_mental_state_attribution": "suspect someone wants to offer and is scared to",
    "ce_supportive_use": "Giving that person room to speak could settle this in seconds",
    "sys_consequence_reasoning": "Equal worth and fast action are where I land"
  },
  {
    "sys_consequence_reasoning": "five walk away if one stays",
    "ce_mental_state_attribution": "think at least one person might be ready to insist on taking my place"
  },
  {
    "ce_mental_state_attribution": "bet somebody is quietly leaning that way",
    "ce_supportive_use": "If so, I'd back them up and help everyone else load",
    "sys_consequence_reasoning": "respecting someone's own choice against imposing mine"
  },
  {
    "sys_consequence_reasoning": "My one life against five isn't a close contest for me",
    "ce_mental_state_attribution": "expect the crew wants to push off the moment the boat is full",
    "ce_supportive_use": "announce it, help load, shove the boat clear"
  },
  {
    "sys_consistent_procedure": "propose a draw within a minute and commit to whatever it says",
    "ce_mental_state_attribution": "most of the others are hoping someone else steps up",
    "sys_consequence_reasoning": "my survival instinct against the group's need for a decision right now",
    "ce_supportive_use": "shared process spares everyone that ugly waiting"
  },
  {
    "sys_consequence_reasoning": "Five people leaving beats a standoff that might cost everyone",
    "ce_mental_state_attribution": "imagine the others are torn between relief and shame",
    "ce_supportive_use": "so I'd give them clear jobs: get in, hold on, go"
  }
]
